/* ---------------------------------------------------------------------------
 * interpreter.c - LayerUp custom bytecode VM.
 *
 * A tiny stack machine. Dispatch goes through a 256-entry function-pointer
 * table (g_dispatch), one standalone handler per opcode - there is no central
 * switch, so reversing it means visiting many small functions.
 *
 * The flag-check program lives in bytecode.h (generated by assembler.py) as a
 * plain byte array in .rodata. A later stage will swap that for an AES-CTR
 * blob decrypted at runtime with key material from the unpacking maze.
 *
 * Build:   gcc -O2 -o interpreter interpreter.c          (keep symbols)
 *          gcc -O2 -s -o interpreter interpreter.c        (stripped)
 * Usage:   ./interpreter 'candidate flag'
 *          echo -n 'candidate flag' | ./interpreter
 * Exit:    0 == correct, 1 == wrong / error.
 * ------------------------------------------------------------------------- */

#include <stdint.h>
#include <stdio.h>
#include <stdlib.h>
#include <string.h>

#include "bytecode.h"

#define STACK_MAX 256
#define VAR_MAX   8

typedef struct {
    uint32_t       stack[STACK_MAX];
    int            sp;
    uint32_t       var[VAR_MAX];
    const uint8_t *code;
    uint32_t       code_len;
    uint32_t       pc;
    const uint8_t *input;
    uint32_t       input_len;
    int            running;
    int            error;
    int            verdict;      /* set by HALT: 1 == correct */
} VM;

/* --- stack helpers -------------------------------------------------------- */

static void vm_fault(VM *vm)
{
    vm->error = 1;
    vm->running = 0;
}

static void vm_push(VM *vm, uint32_t v)
{
    if (vm->sp >= STACK_MAX) { vm_fault(vm); return; }
    vm->stack[vm->sp++] = v;
}

static uint32_t vm_pop(VM *vm)
{
    if (vm->sp <= 0) { vm_fault(vm); return 0; }
    return vm->stack[--vm->sp];
}

static uint32_t fetch32(VM *vm)
{
    if (vm->pc + 4 > vm->code_len) { vm_fault(vm); return 0; }
    uint32_t v = (uint32_t)vm->code[vm->pc]
               | ((uint32_t)vm->code[vm->pc + 1] << 8)
               | ((uint32_t)vm->code[vm->pc + 2] << 16)
               | ((uint32_t)vm->code[vm->pc + 3] << 24);
    vm->pc += 4;
    return v;
}

static uint32_t fetch16(VM *vm)
{
    if (vm->pc + 2 > vm->code_len) { vm_fault(vm); return 0; }
    uint32_t v = (uint32_t)vm->code[vm->pc]
               | ((uint32_t)vm->code[vm->pc + 1] << 8);
    vm->pc += 2;
    return v;
}

static uint8_t fetch8(VM *vm)
{
    if (vm->pc + 1 > vm->code_len) { vm_fault(vm); return 0; }
    return vm->code[vm->pc++];
}

static uint32_t rol32(uint32_t v, uint32_t c)
{
    c &= 31u;
    return c ? ((v << c) | (v >> (32u - c))) : v;
}

/* --- one handler per opcode ---------------------------------------------- */

static void op_push(VM *vm)   { vm_push(vm, fetch32(vm)); }

static void op_load(VM *vm)
{
    uint32_t idx = vm_pop(vm);
    vm_push(vm, idx < vm->input_len ? (uint32_t)vm->input[idx] : 0u);
}

static void op_len(VM *vm)    { vm_push(vm, vm->input_len); }

static void op_add(VM *vm)
{
    uint32_t b = vm_pop(vm), a = vm_pop(vm);
    vm_push(vm, a + b);
}

static void op_sub(VM *vm)
{
    uint32_t b = vm_pop(vm), a = vm_pop(vm);
    vm_push(vm, a - b);
}

static void op_xor(VM *vm)
{
    uint32_t b = vm_pop(vm), a = vm_pop(vm);
    vm_push(vm, a ^ b);
}

static void op_mul(VM *vm)
{
    uint32_t b = vm_pop(vm), a = vm_pop(vm);
    vm_push(vm, a * b);
}

static void op_rol(VM *vm)
{
    uint32_t c = vm_pop(vm), v = vm_pop(vm);
    vm_push(vm, rol32(v, c));
}

static void op_shr(VM *vm)
{
    uint32_t c = vm_pop(vm), v = vm_pop(vm);
    vm_push(vm, v >> (c & 31u));
}

static void op_and(VM *vm)
{
    uint32_t b = vm_pop(vm), a = vm_pop(vm);
    vm_push(vm, a & b);
}

static void op_dup(VM *vm)
{
    if (vm->sp <= 0) { vm_fault(vm); return; }
    vm_push(vm, vm->stack[vm->sp - 1]);
}

static void op_swap(VM *vm)
{
    if (vm->sp < 2) { vm_fault(vm); return; }
    uint32_t t = vm->stack[vm->sp - 1];
    vm->stack[vm->sp - 1] = vm->stack[vm->sp - 2];
    vm->stack[vm->sp - 2] = t;
}

static void op_pop(VM *vm)    { (void)vm_pop(vm); }

static void op_cmp_eq(VM *vm)
{
    uint32_t b = vm_pop(vm), a = vm_pop(vm);
    vm_push(vm, a == b ? 1u : 0u);
}

static void op_jz(VM *vm)
{
    uint32_t target = fetch16(vm);
    uint32_t cond = vm_pop(vm);
    if (!vm->error && cond == 0) {
        if (target >= vm->code_len) { vm_fault(vm); return; }
        vm->pc = target;
    }
}

static void op_jmp(VM *vm)
{
    uint32_t target = fetch16(vm);
    if (vm->error) return;
    if (target >= vm->code_len) { vm_fault(vm); return; }
    vm->pc = target;
}

static void op_halt(VM *vm)
{
    vm->verdict = (vm_pop(vm) == 1u) ? 1 : 0;
    vm->running = 0;
}

static void op_storev(VM *vm)
{
    uint8_t slot = fetch8(vm);
    uint32_t v = vm_pop(vm);
    if (slot >= VAR_MAX) { vm_fault(vm); return; }
    vm->var[slot] = v;
}

static void op_loadv(VM *vm)
{
    uint8_t slot = fetch8(vm);
    if (slot >= VAR_MAX) { vm_fault(vm); return; }
    vm_push(vm, vm->var[slot]);
}

static void op_invalid(VM *vm) { vm_fault(vm); }

/* --- dispatch table ------------------------------------------------------- */

typedef void (*handler_fn)(VM *);
static handler_fn g_dispatch[256];

static void build_dispatch(void)
{
    for (int i = 0; i < 256; i++)
        g_dispatch[i] = op_invalid;

    g_dispatch[0x3C] = op_push;
    g_dispatch[0x9A] = op_load;
    g_dispatch[0x5E] = op_len;
    g_dispatch[0x71] = op_add;
    g_dispatch[0x24] = op_sub;
    g_dispatch[0xB8] = op_xor;
    g_dispatch[0x4D] = op_mul;
    g_dispatch[0xE2] = op_rol;
    g_dispatch[0x53] = op_shr;
    g_dispatch[0x2F] = op_and;
    g_dispatch[0x17] = op_dup;
    g_dispatch[0xCA] = op_swap;
    g_dispatch[0x66] = op_pop;
    g_dispatch[0x8F] = op_cmp_eq;
    g_dispatch[0xD3] = op_jz;
    g_dispatch[0x1B] = op_jmp;
    g_dispatch[0x7B] = op_halt;
    g_dispatch[0x42] = op_storev;
    g_dispatch[0xAE] = op_loadv;
}

/* --- driver --------------------------------------------------------------- */

static int run(const uint8_t *input, uint32_t input_len)
{
    VM vm;
    memset(&vm, 0, sizeof(vm));
    vm.code      = g_bytecode;
    vm.code_len  = g_bytecode_len;
    vm.input     = input;
    vm.input_len = input_len;
    vm.running   = 1;

    while (vm.running) {
        if (vm.pc >= vm.code_len) { vm_fault(&vm); break; }
        uint8_t op = vm.code[vm.pc++];
        g_dispatch[op](&vm);
    }
    return (!vm.error && vm.verdict) ? 1 : 0;
}

int main(int argc, char **argv)
{
    build_dispatch();

    unsigned char buf[4096];
    uint32_t len = 0;

    if (argc > 1) {
        size_t n = strlen(argv[1]);
        if (n > sizeof(buf)) n = sizeof(buf);
        memcpy(buf, argv[1], n);
        len = (uint32_t)n;
    } else {
        size_t n = fread(buf, 1, sizeof(buf), stdin);
        /* drop a single trailing newline if present */
        if (n > 0 && buf[n - 1] == '\n') n--;
        len = (uint32_t)n;
    }

    if (run(buf, len)) {
        puts("Correct!");
        return 0;
    }
    puts("Wrong.");
    return 1;
}
